from urllib.parse import urlparse

ALLOWED = {"ops.bank.internal", "portal.vendor.example", "www.npci.org.in"}
IRREVERSIBLE = ("pay", "confirm", "submit", "reverse", "delete", "approve")

class Policy:
    def __init__(self, session, approver, max_steps=60):
        self.s, self.approver, self.steps = session, approver, 0
        self.max_steps = max_steps

    def check(self, action: dict) -> dict:
        self.steps += 1
        if self.steps > self.max_steps:
            return {"deny": "step limit reached"}
        if urlparse(self.s.current_url).hostname not in ALLOWED:
            return {"deny": "domain not on the allowlist"}
        if action["name"] == "left_click":
            label = self.s.element_label_at(action["input"]["coordinate"]).lower()
            if any(word in label for word in IRREVERSIBLE):
                if not self.approver.confirm(label, self.s.screenshot()):
                    return {"deny": "person declined"}
        if action["name"] == "type" and self.s.focused_is_password():
            self.s.fill_from_vault()               # the model never sees the secret
            return {"handled": "credential filled from vault"}
        self.s.record(action)
        return {"allow": True}
